using symbol "std:io" @print;

data Item {value:u64;}

proc borrow_region()->void {
 owned region r:Item<-make Item(capacity=256u64){value<-1u64};
 proc view=proc(v:u64 in o)->u64 where {region o:Item} {return v;};
 ref result=view(root(r).value); result <-2u64; behave @print(root(r).value);
}
borrow_region();

proc borrow_lexical()->void {
 val input=1u64;
 proc view=proc(v:u64 in o)->u64 where {owner o} {return v;};
 ref result=view(input); result <-2u64; behave @print(input);
}
borrow_lexical();

proc independent()->void {
 val input=1u64;
 proc view=proc(v:u64 in o)->u64 where {owner o} {return v+1u64;};
 ref result=view(input); result <-3u64; behave @print(input); behave @print(result);
}
independent();

proc select_result(flag:bool)->void {
 val input=1u64;
 proc first=proc(v:u64 in o)->u64 where {owner o} {return v;};
 proc second=proc(v:u64 in o)->u64 where {owner o} {return v+1u64;};
 proc selected=if(flag){first}else{second};
 ref result=selected(input); result<-3u64; behave @print(input); behave @print(result);
}
select_result(true);select_result(false);

proc borrow_cleanup()->void {
 val input=1u64;
 proc view=proc(v:u64 in o)->u64 where {owner o} {defer {v<-2u64;}; return v;};
 ref result=view(input); behave @print(result);
}
borrow_cleanup();

proc selected_cleanup(flag:bool)->void {
 val input=1u64;
 proc first=proc(v:u64 in o)->u64 where {owner o} {defer {v<-2u64;}; return v;};
 proc second=proc(v:u64 in o)->u64 where {owner o} {return v+1u64;};
 proc selected=if(flag){first}else{second};
 ref result=selected(input); behave @print(input); behave @print(result);
}
selected_cleanup(true);selected_cleanup(false);

