using symbol "std:io" @print;
data Item {value:u64;}
proc run()->void {
  owned region r:Item<-make Item(capacity=256u64){value<-1u64};
  proc view=proc()->u64 {return root(r).value;};
  ref result=view();
  result<-2u64;
  behave @print(root(r).value);
}
run();

using symbol "std:io" @print;
data Item {value:u64;}
proc run()->void {
  owned region r:Item<-make Item(capacity=256u64){value<-1u64};
  proc action=proc(v:u64 in o)->u64 where {region o:Item} {return v;};
  defer {{ref value=action(root(r).value); behave @print(value);}};
}
run();
